// k路归并:使用最小堆同时归并k个有序段
void kWayMerge(vector<vector<int>>&segments,vector<int>&out){
    priority_queue<pair<int,int>,vector<pair<int,int>>,greater<>>pq;
    vector<int>idx(segments.size(),0);
    for(int i=0;i<segments.size();i++)if(idx[i]<segments[i].size())pq.push({segments[i][idx[i]],i});
    while(!pq.empty()){auto[v,i]=pq.top();pq.pop();out.push_back(v);idx[i]++;if(idx[i]<segments[i].size())pq.push({segments[i][idx[i]],i});}
}
