#include <iostream>
using namespace std;
const int N = 100005;
long long tree[N << 2];
int n;

void build(int l, int r, int rt) {
    if (l == r) { cin >> tree[rt]; return; }
    int mid = (l + r) >> 1;
    build(l, mid, rt << 1);
    build(mid + 1, r, rt << 1 | 1);
    tree[rt] = tree[rt << 1] + tree[rt << 1 | 1];
}

void update(int pos, long long val, int l, int r, int rt) {
    if (l == r) { tree[rt] += val; return; }
    int mid = (l + r) >> 1;
    if (pos <= mid) update(pos, val, l, mid, rt << 1);
    else update(pos, val, mid + 1, r, rt << 1 | 1);
    tree[rt] = tree[rt << 1] + tree[rt << 1 | 1];
}

long long query(int L, int R, int l, int r, int rt) {
    if (L <= l && r <= R) return tree[rt];
    int mid = (l + r) >> 1;
    long long ans = 0;
    if (L <= mid) ans += query(L, R, l, mid, rt << 1);
    if (R > mid) ans += query(L, R, mid + 1, r, rt << 1 | 1);
    return ans;
}

int main() {
    int m; cin >> n >> m;
    build(1, n, 1);
    while (m--) {
        int op, x, y;
        cin >> op >> x >> y;
        if (op == 1) update(x, y, 1, n, 1);
        else cout << query(x, y, 1, n, 1) << endl;
    }
    return 0;
}

