    int mid = (l + r) >> 1;
    if (pos <= mid)
        update(pos, val, l, mid, rt << 1);
    else
        update(pos, val, mid + 1, r, rt << 1 | 1);
    tree[rt] = max(tree[rt << 1], tree[rt << 1 | 1]);
