        for (int j = i + 1; j < step - 1; j++) {
            d[j][0] = old[j + 1][0];
            d[j][1] = old[j + 1][1];
        }
        dfs(step - 1);
        for (int j = 0; j < step; j++) {
            d[j][0] = old[j][0];
            d[j][1] = old[j][1];
        }
    }
}

