using namespace std;
const int N = 1010;
int memo[N][N];

int f(int n, int m) {
    if (n <= 1) return 0;
    if (m == 1) return n - 1;
    if (memo[n][m] != -1) return memo[n][m];
    int ans = n;
    for (int i = 1; i < n; i++) {
        int t = max(f(i, m - 1), f(n - i - 1, m)) + 1;
        if (t < ans) ans = t;
    }
    return memo[n][m] = ans;
}

int g(int n, int m) {
    int dp[N][N];
    memset(dp, 0x3f, sizeof(dp));
    for (int i = 1; i <= n; i++) dp[i][1] = i - 1;
    for (int i = 1; i <= n; i++) dp[1][i] = 0;
    for (int i = 2; i <= n; i++) {
        for (int j = 2; j <= m; j++) {
            for (int k = 1; k < i; k++) {
                dp[i][j] = min(dp[i][j], max(dp[k][j - 1], dp[i - k - 1][j]) + 1);
            }
        }
    }
    return dp[n][m];
}

int main() {
    int n, m;
    cin >> n >> m;
    memset(memo, -1, sizeof(memo));
    cout << f(n, m) << " " << g(n, m) << endl;
